alter table public.boq_items drop constraint if exists boq_items_source_sheet_check;drop policy if exists boq_items_admin_insert on public.boq_items;create policy boq_items_admin_insert on public.boq_items for insert to authenticated with check(public.current_user_role() in ('admin','site_manager'));grant insert on public.boq_items to authenticated;drop trigger if exists audit_boq_items on public.boq_items;create trigger audit_boq_items after insert or update or delete on public.boq_items for each row execute function public.capture_udu_audit();